using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public static class Optimization641Tests {
  public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(folder,"profile"));var log=new StringBuilder();int checks=0;Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);checks++;log.AppendLine("PASS "+message);};try{
   var original=new AppSettings{FormatVersion=3,Theme=GearTheme.Светлая,Language=GearLanguage.English,Quality=GearQuality.Подробный,OrbitSensitivity=17,SnapEnabled=false,SnapStep=2.75,AnimationScale=3.25,AutoSave=false,AutoSaveSeconds=123};original.Colors["Panel"]="#334455";var clone=original.Clone();foreach(var p in typeof(AppSettings).GetProperties(BindingFlags.Public|BindingFlags.Instance).Where(p=>p.CanRead&&p.CanWrite&&p.Name!="Colors"))check(object.Equals(p.GetValue(original,null),p.GetValue(clone,null)),"clone retains "+p.Name);clone.Colors["Panel"]="#112233";check(original.Colors["Panel"]=="#334455","palette clone has independent storage");
   AppSettings.Commit(new AppSettings());using(var form=new Form())using(var label=new Label{Text="Настройки"})using(var edit=new TextBox{Text="Имя пользовательского проекта"}){form.Controls.Add(label);form.Controls.Add(edit);form.Show();AppSettings.Apply(form);Application.DoEvents();int repaints=0;label.Invalidated+=(s,e)=>repaints++;int ar=AppSettings.AppearanceRevision,lr=AppSettings.LanguageRevision;using(var scene=new WpfScene()){var r=Engine.Calculate(Engine.Starter(4));r.Model=CadBuilder.Build(r);scene.SetResult(r,false);var environment=scene.PerformanceEnvironment;var mesh=scene.Nodes.First().Source;
    foreach(string setting in new[]{"speed","snap","orbit","autosave"}){var draft=AppSettings.Current.Clone();if(setting=="speed")draft.AnimationScale=2.5;if(setting=="snap"){draft.SnapEnabled=false;draft.SnapStep=2;}if(setting=="orbit")draft.OrbitSensitivity=12;if(setting=="autosave"){draft.AutoSave=false;draft.AutoSaveSeconds=120;}AppSettings.Commit(draft);check(ReferenceEquals(environment,scene.PerformanceEnvironment),setting+" preserves 3D environment");check(ReferenceEquals(mesh,scene.Nodes.First().Source),setting+" preserves model mesh");}
    check(repaints==0,"unrelated preferences do not invalidate styled labels");check(AppSettings.AppearanceRevision==ar&&AppSettings.LanguageRevision==lr,"unrelated preferences keep visual revisions");check(AppSettings.LoadFrom(AppSettings.SettingsPath).AnimationScale==2.5&&File.Exists(AppSettings.SettingsPath+".bak"),"optimized commits retain persistence and backup");
    AppSettings.SetLanguage(GearLanguage.English);check(label.Text=="Preferences","language still updates visible controls immediately");check(edit.Text=="Имя пользовательского проекта","language preserves editable user data");check(AppSettings.LanguageRevision==lr+1,"language revision advances");check(I18n.T("Frame 10 · X 0.25 mm")=="Frame 10 · X 0.25 mm","ASCII fast path preserves content");check(I18n.T("Параметр 42: Габарит 80 мм; Выход 30 об/мин")=="Parameter 42: Size 80 mm; Output 30 rpm","cached generated status retains full translation");for(int i=0;i<1100;i++)I18n.T("Параметр "+i+": Габарит 80 мм");var cached=typeof(I18n).GetField("Translated",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);check((int)cached.GetType().GetProperty("Count").GetValue(cached,null)<=1024,"translation cache stays bounded");check(I18n.T("Параметр 42: Габарит 80 мм; Выход 30 об/мин")=="Parameter 42: Size 80 mm; Output 30 rpm","cache eviction preserves translation");AppSettings.SetLanguage(GearLanguage.Русский);check(label.Text=="Настройки"&&I18n.T("Параметр 42")=="Параметр 42","Russian roundtrip ignores English cache");
    var colors=AppSettings.Current.Clone();colors.Colors["Panel"]="#123456";var before=scene.PerformanceEnvironment;AppSettings.Commit(colors);check(label.BackColor.ToArgb()==Color.FromArgb(0x12,0x34,0x56).ToArgb(),"palette updates existing controls");check(!ReferenceEquals(before,scene.PerformanceEnvironment),"appearance change refreshes 3D environment");colors=AppSettings.Current.Clone();colors.Theme=GearTheme.Светлая;AppSettings.Commit(colors);check(form.BackColor==UiPalette.Get("Window"),"theme still updates root window");var quality=AppSettings.Current.Clone();quality.Quality=GearQuality.Подробный;AppSettings.Commit(quality);var timer=System.Diagnostics.Stopwatch.StartNew();while(!scene.Ready&&timer.Elapsed.TotalSeconds<30){Application.DoEvents();System.Threading.Thread.Sleep(10);}check(scene.Ready&&scene.Error==null&&scene.Nodes.Count>0&&scene.Result!=null&&scene.Result.Model!=null&&scene.Result.Model.Valid,"quality change keeps valid rebuilt preview");
   }form.Close();}
   var palette=new AppSettings();palette.Colors["Panel"]="#112233";check(UiPalette.Get(palette,"Panel").ToArgb()==Color.FromArgb(0x11,0x22,0x33).ToArgb(),"palette parses custom value");palette.Colors["Panel"]="#445566";check(UiPalette.Get(palette,"Panel").ToArgb()==Color.FromArgb(0x44,0x55,0x66).ToArgb(),"palette cache observes changed override");
   // SHA256 of every point, normal and index produced by the frozen 6.4.0 implementation.
   double[] radii={.0001,.1,2.15,1000};string[] expected={"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855","7569C4D084939453C32F66ACCFD1294CFB9A4D02D0BD940CBF9B90DD56146E80","E1983409470ABAD9C321E9D0AE9D5EF73993ED0FD7840472FE5400A2C2C45586","EF6EDE93FFFD98E768DD63ADEE556ECBE88DE213273785145B2A56200CF40D9B"};for(int i=0;i<radii.Length;i++)check(PerformanceTests.Fingerprint(new AnalyticSolid{Sphere=new[]{12.25,-3.5,4.75,radii[i]}}.Mesh())==expected[i],"sphere geometry identical to 6.4.0 at radius "+radii[i]);check(PerformanceTests.Fingerprint(new AnalyticSolid{Revolve=new[]{new[]{3.0,-1.0},new[]{5.0,-1.0},new[]{5.0,2.0},new[]{3.0,2.0}}}.Mesh())=="AF307B55F7D39AFC2C2579B672EDF82401D1E61A7F4807A568377DF5BA181A0A","bearing race geometry identical to 6.4.0");
   File.WriteAllText(Path.Combine(folder,"optimization641-results.txt"),log+"PASS "+checks+" assertions",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"optimization641-error.txt"),log+ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
